	public boolean isBypassed(int j) {
		long uj = ((long) j);
		return ((Long.compareUnsigned(uj, (this.@bypassed_).size()) < 0) && (((this.@bypassed_).a[(int) uj] & 0xFF) != 0));
	}

	public cpp.RefD nodeSumDqdh(int n) {
		return new cpp.RefD.Arr(((this.@xnode_).@sumdqdh).a, (int) ((long) n));
	}

